function L(s, ...args) {
  let out = LANG === "fr" && FR[s] !== undefined ? FR[s] : s;
  if (args.length) out = out.replace(/\{(\d+)\}/g, (m, i) => args[+i] ?? "");
  return out;
}

// Textes fixes de la page : on garde l'anglais d'origine de chaque nœud pour pouvoir rebasculer
const I18N_NODES = [];
function collectI18n() {
  const walk = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  let n;
  while ((n = walk.nextNode())) {
    const t = n.nodeValue.trim();
    if (t && FR[t] !== undefined && !n.parentElement.closest("script")) I18N_NODES.push({ n, t, raw: n.nodeValue });
  }
  document.querySelectorAll("[title]").forEach(el => { if (FR[el.title] !== undefined) I18N_NODES.push({ el, attr: "title", t: el.title }); });
  document.querySelectorAll("[placeholder]").forEach(el => { if (FR[el.placeholder] !== undefined) I18N_NODES.push({ el, attr: "placeholder", t: el.placeholder }); });
}
function setLang(lang) {
  lang = lang === "fr" ? "fr" : "en";
  if (!I18N_NODES.length) collectI18n();
  if (lang === LANG && setLang.done) return;
  LANG = lang; setLang.done = true;
  document.documentElement.lang = lang;
  for (const x of I18N_NODES) {
    if (x.n) x.n.nodeValue = x.raw.replace(x.t, L(x.t));
    else x.el.setAttribute(x.attr, L(x.t));
  }
}
